package com.newland.nsdk.core.api.external.crypto;

import com.newland.nsdk.core.api.common.Module;
import com.newland.nsdk.core.api.common.crypto.AsymEncodingMode;
import com.newland.nsdk.core.api.external.keymanager.ExtKeyManager;
import com.newland.nsdk.core.api.common.crypto.AsymAlgorithmParameters;
import com.newland.nsdk.core.api.common.crypto.CipherOutput;
import com.newland.nsdk.core.api.common.crypto.CipherType;
import com.newland.nsdk.core.api.common.crypto.MACOutput;
import com.newland.nsdk.core.api.common.crypto.MACType;
import com.newland.nsdk.core.api.common.crypto.PaddingMode;
import com.newland.nsdk.core.api.common.keymanager.AsymmetricKey;
import com.newland.nsdk.core.api.common.keymanager.KeyUsage;
import com.newland.nsdk.core.api.common.keymanager.SymmetricKey;
import com.newland.nsdk.core.api.common.exception.NSDKException;

/**
 * <b>[External Module]</b> Provides the ability to encrypt/decrypt data with keys in the PIN pad.
 *
 * <p>How to get this module:</p>
 * <pre>
 *     ExtCrypto extCrypto = (ExtCrypto)ExtNSDKModuleManagerImpl.getInstance().getModule(ModuleType.EXT_CRYPTO);
 * </pre>
 */
public interface ExtCrypto extends Module {
    /**
     * Generates MAC for a block of data with the specified key.
     *
     * <p>Example:</p>
     * <pre>
     *     byte keyId = 2;
     *     MACType macType = MACType.TDES_X99;
     *
     *     byte[] data = ISOUtils.hex2byte("88888881113366677883373215563223abcdeffdaabbccdd");
     *
     *     try {
     *         MACOutput macOutput = extCrypto.generateMAC(keyId, macType, null, data);
     *         if(macOutput != null){
     *             // Handle the MAC result: macOutput.getData()
     *         }
     *     } catch(NSDKException e) {
     *         // Handle the exception
     *     }
     * </pre>
     *
     * @param keyID   <b>[Required]</b> The key used to generate MAC. This key shall already be generated via {@link ExtKeyManager#generateKey} first.
     * @param macType <b>[Required]</b> MAC type, see {@link MACType}
     * @param iv      <b>[Optional]</b> Initial Vector required for CBC mode. 8 bytes for TDES, 16 bytes for AES.
     * @param data    <b>[Required]</b> Data for MAC generation.
     * @return MAC output. See {@link MACOutput}.
     * @throws NSDKException
     */
    MACOutput generateMAC(byte keyID, MACType macType, byte[] iv, byte[] data) throws NSDKException;

    /**
     * Encrypts data with the key which is already exist in the PIN pad.
     *
     * <p>Example:</p>
     * <pre>
     *     // Case 1: External device based on Forth firmware.
     *     SymmetricKey key = new SymmetricKey();
     *     key.setKeyID((byte) 2);
     *     key.setKeyUsage(KeyUsage.DATA);
     *
     *     byte[] data = ISOUtils.hex2byte("88888881113366677883373215563223abcdeffdaabbccdd");
     *
     *     try {
     *         CipherOutput cipherOutput = extCrypto.encrypt(key, CipherType.DES_ECB, PaddingMode.NONE, null, data);
     *         if(cipherOutput != null){
     *             // Handle the encrypted data: cipherOutput.getData()
     *         }
     *     } catch(NSDKException e) {
     *         // Handle the exception
     *     }
     *
     *     // Case 2: External device not based on Forth firmware.
     *     SymmetricKey key = new SymmetricKey();
     *     key.setKeyID((byte) 2);
     *
     *     byte[] data = ISOUtils.hex2byte("88888881113366677883373215563223abcdeffdaabbccdd");
     *
     *     try {
     *         CipherOutput cipherOutput =  extCrypto.encrypt(key, CipherType.DES_ECB, null, null, data);
     *         if(cipherOutput != null){
     *              // Handle the encrypted data: cipherOutput.getData()
     *         }
     *     } catch(NSDKException e) {
     *         // Handle the exception
     *     }
     *
     * </pre>
     *
     * @param key         <b>[Required]</b> The key used to encrypt data. see {@link SymmetricKey}. This key shall already be generated by {@link ExtKeyManager#generateKey} before.
     *                    <ul>
     *                    <li>For external device based on Forth firmware, the following parameters are required:</li>
     *                        <ul>
     *                        <li>Key index</li>
     *                        <li>Key usage</li>
     *                        </ul>
     *                    <li>Otherwise, only key index is required.</li>
     *                    </ul>
     * @param cipherType  <b>[Required]</b> Cipher type. See {@link CipherType}
     * @param paddingMode <b>[Optional]</b> Padding mode, required for external device with Forth firmware. See {@link PaddingMode}. Default value is {@link PaddingMode#NONE}.
     * @param iv          <b>[Optional]</b> Initial vector required when CBC mode. 8 bytes for TDES, 16 bytes for AES.
     * @param data        <b>[Required]</b> Data to be encrypted.
     * @return Encryption result. See {@link CipherOutput}
     * @throws NSDKException
     */
    CipherOutput encrypt(SymmetricKey key, CipherType cipherType, PaddingMode paddingMode, byte[] iv, byte[] data) throws NSDKException;

    /**
     * Decrypts data with the key which is already exist in the PIN pad.
     *
     * <p>Example:</p>
     * <pre>
     *     // Case 1: External device based on Forth firmware.
     *     SymmetricKey key = new SymmetricKey();
     *     key.setKeyID((byte) 2);
     *     key.setKeyUsage(KeyUsage.DATA);
     *
     *     byte[] data = ISOUtils.hex2byte("DD55F3341D5ECFF5FBC3336594620743D316FC7C3EABE42E");
     *
     *     try {
     *         CipherOutput cipherOutput = extCrypto.decrypt(key, CipherType.DES_ECB, PaddingMode.NONE, null, data);
     *         if(cipherOutput != null){
     *             // Handle the decrypted data: cipherOutput.getData()
     *         }
     *     } catch(NSDKException e) {
     *         // Handle the exception
     *     }
     *
     *     // Case 2: External device not based on Forth firmware.
     *     Key key = new Key();
     *     key.setKeyID((byte) 2);
     *
     *     byte[] data = ISOUtils.hex2byte("DD55F3341D5ECFF5FBC3336594620743D316FC7C3EABE42E");
     *
     *     try {
     *         CipherOutput cipherOutput = extCrypto.decrypt(key, CipherType.ECB, null, null, data);
     *         if(cipherOutput != null){
     *             // Handle the decrypted data: cipherOutput.getData()
     *         }
     *     } catch(NSDKException e) {
     *         // Handle the exception
     *     }
     *
     * </pre>
     *
     * @param key         The key used to decrypt data, see {@link SymmetricKey}. This key shall be generated by {@link ExtKeyManager#generateKey} before.
     *                    <ul>
     *                    <li>For external device based on Forth firmware, the following parameters are required:</li>
     *                        <ul>
     *                        <li>Key index</li>
     *                        <li>Key usage: Default key usage {@link KeyUsage#DATA}</li>
     *                        </ul>
     *                    <li>Otherwise, only key index is required.</li>
     *                    </ul>
     * @param cipherType  <b>[Required]</b> Cipher type. See {@link CipherType}
     * @param paddingMode <b>[Optional]</b> Padding mode, required for external device with Forth firmware. See {@link PaddingMode}. Default value is {@link PaddingMode#NONE}.
     * @param iv          <b>[Optional]</b> Initial vector required when CBC mode. 8 bytes for TDES, 16 bytes for AES.
     * @param data        <b>[Required]</b> Data to be decrypted.
     * @return Decryption result. See {@link CipherOutput}
     * @throws NSDKException
     */
    CipherOutput decrypt(SymmetricKey key, CipherType cipherType, PaddingMode paddingMode, byte[] iv, byte[] data) throws NSDKException;

    /**
     * Encrypts data with the asymmetric key which is already exist in the PIN pad.
     *
     * <p>Example:</p>
     * <pre>
     *     AsymmetricKey key = new AsymmetricKey();
     *     key.setKeyID((byte) 3);
     *     key.setKeyUsage(AsymKeyUsage.DATA);
     *     key.setKeyType(AsymKeyType.RSA);
     *
     *     AsymAlgorithmParameters parameters = new AsymAlgorithmParameters();
     *     parameters.setMessageDigestType(MessageDigestType.SHA256);
     *     parameters.setEncodingMode(AsymEncodingMode.PKCS_V21);
     *     parameters.setCryptoMode(AsymCryptoMode.PUBLIC);
     *
     *     byte[] data = ISOUtils.hex2byte("0102030405060708090A0B0C0D0E0F");
     *
     *     try {
     *         byte[] result = extCrypto.encryptAsym(key, parameters, data);
     *     } catch (NSDKException e) {
     *         // Handle the error
     *     }
     * </pre>
     *
     * @param key                 <b>[Required]</b> The key used to encrypt data, see {@link AsymmetricKey}. This key shall be generated by {@link ExtKeyManager#generateKey} before.
     *                            <ul>
     *                            <li><b>[Required]</b> Key ID</li>
     *                            <li><b>[Required]</b> Key usage</li>
     *                            <li><b>[Required]</b> Key type</li>
     *                            </ul>
     * @param algorithmParameters <b>[Required]</b> Algorithm parameters, see {@link AsymAlgorithmParameters}.
     *                            <ul>
     *                            <li><b>[Optional]</b> Message digest type is required when encoding mode is not {@link AsymEncodingMode#PKCS_V15}.</li>
     *                            <li><b>[Required]</b> Encoding mode</li>
     *                            <li><b>[Required]</b> Crypto mode</li>
     *                            </ul>
     * @param data                <b>[Required]</b> Data to be encrypted.
     * @return Encryption result.
     * @throws NSDKException
     */
    byte[] encryptAsym(AsymmetricKey key, AsymAlgorithmParameters algorithmParameters, byte[] data) throws NSDKException;

    /**
     * Decrypts data with the asymmetric key which is already exist in the PIN pad.
     *
     * <p>Example:</p>
     * <pre>
     *     AsymmetricKey key = new AsymmetricKey();
     *     key.setKeyID((byte) 3);
     *     key.setKeyUsage(AsymKeyUsage.DATA);
     *     key.setKeyType(AsymKeyType.RSA);
     *
     *     AsymAlgorithmParameters parameters = new AsymAlgorithmParameters();
     *     parameters.setMessageDigestType(MessageDigestType.SHA256);
     *     parameters.setEncodingMode(AsymEncodingMode.PKCS_V21);
     *     parameters.setCryptoMode(AsymCryptoMode.PUBLIC);
     *
     *     try {
     *         byte[] decryptedData = extCrypto.decryptAsym(key, parameters, encryptedData);
     *     } catch (NSDKException e) {
     *         // Handle the error.
     *     }
     * </pre>
     *
     * @param key                 <b>[Required]</b> The key used to decrypt data, see {@link AsymmetricKey}. This key shall be generated by {@link ExtKeyManager#generateKey} before.
     *                            <ul>
     *                            <li><b>[Required]</b> Key ID</li>
     *                            <li><b>[Required]</b> Key usage</li>
     *                            <li><b>[Required]</b> Key type</li>
     *                            </ul>
     * @param algorithmParameters <b>[Required]</b> Algorithm parameters, see {@link AsymAlgorithmParameters}.
     *                            <ul>
     *                            <li><b>[Optional]</b> Message digest type is required when encoding mode is not {@link AsymEncodingMode#PKCS_V15}.</li>
     *                            <li><b>[Required]</b> Encoding mode</li>
     *                            <li><b>[Required]</b> Crypto mode</li>
     *                            </ul>
     * @param data                <b>[Required]</b> Data to be decrypted.
     * @return Decryption result.
     * @throws NSDKException
     */
    byte[] decryptAsym(AsymmetricKey key, AsymAlgorithmParameters algorithmParameters, byte[] data) throws NSDKException;

    /**
     * Gets signature data.
     *
     * <p>Example:</p>
     * <pre>
     *      AsymmetricKey key = new AsymmetricKey();
     *      key.setKeyID((byte) 10);
     *      key.setKeyUsage(AsymKeyUsage.AUTH);
     *      key.setKeyType(AsymKeyType.RSA);
     *
     *      AsymAlgorithmParameters parameters = new AsymAlgorithmParameters();
     *      parameters.setMessageDigestType(MessageDigestType.SHA256);
     *      parameters.setEncodingMode(AsymEncodingMode.PKCS_V15);
     *
     *      String originalString = "12345678";
     *      byte[] hash = null;
     *      byte[] signedData = null;
     *
     *      try {
     *          MessageDigest digest = MessageDigest.getInstance("SHA-256");
     *          hash = digest.digest(originalString.getBytes());
     *          signedData = extCrypto.signAsym(key, parameters, hash);
     *      } catch (NoSuchAlgorithmException e) {
     *          // Failed to get SHA256 message digest instance.
     *      } catch (NSDKException e) {
     *          // Handle the error.
     *      }
     * </pre>
     *
     * @param key                 <b>[Required]</b> The key used for signature.
     *                            <ul>
     *                            <li><b>[Required]</b> Key ID</li>
     *                            <li><b>[Required]</b> Key usage</li>
     *                            <li><b>[Required]</b> Key type</li>
     *                            </ul>
     * @param algorithmParameters Algorithm parameters, see {@link AsymAlgorithmParameters}.
     *                            <ul>
     *                            <li><b>[Required]</b> Message digest type</li>
     *                            <li><b>[Required]</b> Encoding mode</li>
     *                            </ul>
     * @param hash                <b>[Required]</b> Hash data to be signed.
     * @return Signed data.
     * @throws NSDKException
     */
    byte[] signAsym(AsymmetricKey key, AsymAlgorithmParameters algorithmParameters, byte[] hash) throws NSDKException;

    /**
     * Verifies if the signature is correct.
     *
     * <p>Example:</p>
     * <pre>
     *      AsymmetricKey key = new AsymmetricKey();
     *      key.setKeyId((byte) 10);
     *      key.setKeyUsage(AsymKeyUsage.AUTH);
     *      key.setKeyType(AsymKeyType.RSA);
     *
     *      AsymAlgorithmParameters parameters = new AsymAlgorithmParameters();
     *      parameters.setMessageDigestType(MessageDigestType.SHA256);
     *      parameters.setEncodingMode(AsymEncodingMode.PKCS_V15);
     *
     *      try {
     *          extCrypto.verifyAsym(key, parameters, hash, signedData);
     *      } catch (NoSuchAlgorithmException e) {
     *          // Failed to get SHA256 message digest instance.
     *      } catch (NSDKException e) {
     *          // Handle the error.
     *      }
     * </pre>
     *
     * @param key                 <b>[Required]</b> The key used for signature, see {@link AsymmetricKey}.
     *                            <ul>
     *                            <li><b>[Required]</b> Key ID</li>
     *                            <li><b>[Required]</b> Key usage</li>
     *                            <li><b>[Required]</b> Key type</li>
     *                            </ul>
     * @param algorithmParameters Algorithm parameters, see {@link AsymAlgorithmParameters}.
     *                            <ul>
     *                            <li><b>[Required]</b> Message digest type</li>
     *                            <li><b>[Required]</b> Encoding mode</li>
     *                            </ul>
     * @param hash                <b>[Required]</b> Hash data to be signed.
     * @param signedData          <b>[Required]</b> ExtSignatureInfo data.
     * @throws NSDKException
     */
    void verifyAsym(AsymmetricKey key, AsymAlgorithmParameters algorithmParameters, byte[] hash, byte[] signedData) throws NSDKException;

    /**
     *Get random data
     * @param len <b>[Required]</b> The length of target random data, from 1 to 2048.
     * @return The random data
     * @throws NSDKException
     */
    byte[] getRandom(int len) throws NSDKException;
}
